country_event = {
	id = bio.1

	is_triggered_only = yes
	hide_window = yes

	trigger = {
		has_biogenesis_dlc = yes
	}

	immediate = {
		if = {
			limit = {
				is_hive_empire = no
			}
			start_situation = {
				type = genetic_ascension_situation
				target = root
			}
		}
		else = {
			start_situation = {
				type = genetic_ascension_situation_hive
				target = root
			}
		}
	}
}

