script:
leader_event = {
	id = bio.500
	hide_window = yes

	is_triggered_only = yes

	trigger = {
		exists = owner
		owner = {
			has_valid_civic = civic_hive_familiar_face
		}
		species = {
			has_trait = trait_hive_mind
		}
		OR = {
			leader_class = envoy
			leader_class = official
		}
		OR = {
			AND = {
				exists = envoy_location_country
				NOT = { has_envoy_task = { task = first_contact } }
			}
			is_assigned_to_federation = yes
			is_assigned_to_galcom = yes
		}
	}

	immediate = {
		if = {
			limit = {
				exists = envoy_location_country
				envoy_location_country.species = {
					NOR = {
						is_archetype = MACHINE
						is_archetype = ROBOT
					}
				}
			}
			change_leader_portrait = envoy_location_country.species
			set_leader_flag = familiar_face_changed
		}
		else_if = {
			limit = {
				is_assigned_to_federation = yes
				owner = {
					any_federation_ally = {
						species = {
							NOR = {
								is_archetype = MACHINE
								is_archetype = ROBOT
							}
						}
					}
				}
			}
			owner = {
				random_federation_ally = {
					limit = {
						species = {
							NOR = {
								is_archetype = MACHINE
								is_archetype = ROBOT
							}
						}
					}
					root = {
						change_leader_portrait = prev.species
						set_leader_flag = familiar_face_changed
					}
				}
			}
		}
		else_if = {
			limit = {
				any_galcom_member = {
					species = {
						NOR = {
							is_archetype = MACHINE
							is_archetype = ROBOT
						}
					}
				}
			}
			random_galcom_member = {
				limit = {
					species = {
						NOR = {
							is_archetype = MACHINE
							is_archetype = ROBOT
						}
					}
				}
				root = {
					change_leader_portrait = prev.species
					set_leader_flag = familiar_face_changed
				}
			}
		}
	}
}

